[ExtensionOf(classStr(FreeTextInvoiceDP))]
internal final class METFreeTextInvoiceDP_Extension
{

}

Method.Source:
/// <summary>
/// Populates the invoice header information into the <c>FreeTextInvoiceHeaderFooterTmp</c> table buffer.
/// </summary>
/// <param name="_custInvoiceJour">
/// The <c>CustInvoiceJour</c> record that has the invoice header information.
/// </param>
/// <param name="_companyInfo">
/// The <c>CompanyInfo</c> record that has the company information.
/// </param>
protected void populateFreeTextInvoiceHeaderFooterTmp(CustInvoiceJour _custInvoiceJour, CompanyInfo _companyInfo)
{
    next populateFreeTextInvoiceHeaderFooterTmp(_custInvoiceJour, _companyInfo);

    //TODO:SUJAY: Determine logic to call this method, so that this rebate related initialisations occur only for rebate related report.
    this.populateRebateInvoiceHeaderDetails(_custInvoiceJour);
}

/// <summary>
/// Initalise rebate related information in header temparory table for FreeTextInvoice - Volumentric or Non Volumetric Rebate Invoice report.
/// </summary>
protected void populateRebateInvoiceHeaderDetails(CustInvoiceJour _custInvoiceJour)
{
    //TODO:SUJAY: Determine a logic for following code to be executed only for rebate related report.
    //custInvoiceTable = contract.parmCustInvoiceTable();
    custInvoiceTable = _custInvoiceJour.custInvoiceTable();

    TAMRebateDateTrans          rebateDateTrans;
    InventLocationId            inventLocationId  = InventLocation::find(CustTable::find(custInvoiceTable.OrderAccount).InventLocation).InventLocationId;
    METIndustryKey              industryKey       = METCustTable::find(custInvoiceTable.OrderAccount).IndustryKey;
    SysDocuBrandDetails         brandingDetails   = this.getDocuBrandDetails(industryKey);
    METIndustryKeyTable         industryKeyTable  = METIndustryKeyTable::find(industryKey);

    select firstonly RebateId, RebateFromDate, RebateToDate, RebateDeal from rebateDateTrans
        where rebateDateTrans.RebateTransId == custInvoiceTable.TAMRebateTransId
    join METVolumetricTierDeal, RebateDocumentNotes, Deal from rebateDeal
        where rebateDeal.RecId == rebateDateTrans.RebateDeal
    join tierRateTrans
        where tierRateTrans.TAMRebateDealId == rebateDeal.Deal;

    freeTextInvoiceHeaderFooterTmp.InvoiceNumber = custInvoiceTable.InvoiceId;
    freeTextInvoiceHeaderFooterTmp.InvoiceDate   = custInvoiceTable.InvoiceDate;
    freeTextInvoiceHeaderFooterTmp.Branch        = inventLocationId;
    freeTextInvoiceHeaderFooterTmp.RebateName    = TAMRebateTable::find(rebateDateTrans.RebateId).Description;
    freeTextInvoiceHeaderFooterTmp.Period        = strFmt("@MET:RebatePeriod", rebateDateTrans.RebateFromDate, rebateDateTrans.RebateToDate);
    freeTextInvoiceHeaderFooterTmp.CompanyLogo   = brandingDetails.Image1;
    freeTextInvoiceHeaderFooterTmp.CompanyName   = industryKeyTable.IndustryChannel;
    freeTextInvoiceHeaderFooterTmp.CompanyCoRegNum = brandingDetails.METTaxRegNumber;
    freeTextInvoiceHeaderFooterTmp.CompanyPhone    = brandingDetails.Phone;
    freeTextInvoiceHeaderFooterTmp.CompanyTeleFax  = brandingDetails.TeleFax;
    freeTextInvoiceHeaderFooterTmp.InvoiceToName = custInvoiceTable.custTable_OrderAccount().DirPartyTable_FK().KnownAs;

    LogisticsLocationRoleRecId invoiceRoleRecId = LogisticsLocationRole::findByName(METConstants::InvoiceRole).RecId;
    RefRecId party = custInvoiceTable.custTable_OrderAccount().Party;
    DirPartyPostalAddressView dirPartyPostalAddressView = this.getCustomerAddressByInvoice(party, DirPartyTable::findRec(party).PrimaryAddressLocation, invoiceRoleRecId);

    freeTextInvoiceHeaderFooterTmp.InvoiceToAddress = dirPartyPostalAddressView.Street + METConstants::NextLine
                                            + dirPartyPostalAddressView.City + METConstants::NextLine
                                            + dirPartyPostalAddressView.State + METConstants::NextLine
                                            + dirPartyPostalAddressView.ZipCode + METConstants::NextLine
                                            + dirPartyPostalAddressView.CountryRegionId;

    freeTextInvoiceHeaderFooterTmp.InvoiceToCustNumber = custInvoiceTable.custTable_OrderAccount().AccountNum;
    //rebateInvoiceHeaderTmp.insert();
}

/// <summary>
/// Populates the Invoice details information into the <c>FreeTextInvoiceTmp</c> table buffer.
/// </summary>
/// <param name="_custInvoiceJour">
/// The <c>CustInvoiceJour</c> record that has the invoice header information.
/// </param>
/// <param name="_custInvoiceTrans">
/// The <c>CustInvoiceTrans</c> record that has the invoice details information.
/// </param>
/// <param name="_taxSpec">
/// The <c>TaxSpec</c> class instance that has the taxes information.
/// </param>
/// <param name="_custPaymSchedLine">
/// The <c>CustPaymSchedLine</c> record that has the payment schedules information.
/// </param>
/// <param name="_prepaymentCustTrans">
/// The <c>CustTrans</c> record that has the prepayment information.
/// </param>
/// <param name="_prepaymentTaxTrans">
/// The <c>TaxTrans</c> record that has the prepayment taxes information.
/// </param>
protected void populateFreeTextInvoiceTmp(
    CustInvoiceJour _custInvoiceJour,
    CustInvoiceTrans _custInvoiceTrans,
    TaxSpec _taxSpec,
    CustPaymSchedLine _custPaymSchedLine,
    CustTrans _prepaymentCustTrans,
    TaxTrans _prepaymentTaxTrans)
{
    next populateFreeTextInvoiceTmp(
        _custInvoiceJour,
        _custInvoiceTrans,
        _taxSpec,
        _custPaymSchedLine,
        _prepaymentCustTrans,
        _prepaymentTaxTrans);

    this.populateRebateInvoiceDetails
}

/// <summary>
/// Creates a <c>RebateInvoiceLinesrTmp</c> record.
/// </summary>
protected void populateRebateInvoiceDetails(CustInvoiceJour _custInvoiceJour, CustInvoiceTrans _custInvoiceTrans)
{
    CustInvoiceLine             custInvoiceLine;
    FiscalCalendarPeriod        fiscalCalendarPeriod;
    FiscalCalendar              fiscalCal;
    FiscalCalendarYear          fiscalCalYear;
    FiscalCalendarID            calendarId = FiscalCalendar::find(Ledger::fiscalCalendar(CompanyInfo::current())).CalendarId;

    RecordInsertList rebateInvoiceLineTmpList = new RecordInsertList(tableNum(METRebateInvoiceLineTmp));

    select firstonly METNoOfWeeksForPeriod from fiscalCalendarPeriod
    exists join fiscalCalYear
        where fiscalCalendarPeriod.FiscalCalendarYear == fiscalCalYear.RecId
    exists join fiscalCal
        where fiscalCal.RecId == fiscalCalYear.FiscalCalendar
        && fiscalCal.CalendarId == calendarId
        && fiscalCalendarPeriod.Type == FiscalPeriodType::Operating
        && fiscalCalendarPeriod.StartDate == tierRateTrans.FromDate
        && fiscalCalendarPeriod.EndDate == tierRateTrans.ToDate;

    while select custInvoiceLine
    where custInvoiceLine.ParentRecId == custInvoiceTable.RecId
    {
        rebateInvoiceLineTmp.CommodityGroup = custInvoiceLine.Description;

        if (rebateDeal.METVolumetricTierDeal)
        {
            rebateInvoiceLineTmp.EligibleSales = tierRateTrans.AgEligibleTransAmount;
            rebateInvoiceLineTmp.IsVolumetricTierDeal = NoYes::Yes;

            if (tierRateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate)
            {
                rebateInvoiceLineTmp.Rate = tierRateTrans.EligibleRebate;
            }
        }

        rebateInvoiceLineTmp.GST = Tax::calcTaxAmount(custInvoiceLine.TaxGroup, custInvoiceLine.TaxItemGroup, custInvoiceTable.invoiceDate,
                                                    custInvoiceLine.CurrencyCode, custInvoiceLine.AmountCur, TaxModuleType::FreeTxtInvoice);

        rebateInvoiceLineTmp.TotalRebate = custInvoiceLine.AmountCur;
        rebateInvoiceLineTmp.Message = rebateDeal.RebateDocumentNotes;
        rebateInvoiceLineTmp.AverageWeeklySales = tierRateTrans.WeeklyAverage;
        rebateInvoiceLineTmp.NoOfWeeksForPeriod = fiscalCalendarPeriod.METNoOfWeeksForPeriod;
        rebateInvoiceLineTmpList.add(rebateInvoiceLineTmp);
    }

    rebateInvoiceLineTmpList.insertDatabase();
}
